{
  "tools": [
    {
      "name": "add_component",
      "title": "Add Component",
      "toolset": "scene",
      "description": "Add a component to a game object, optionally setting its properties in the same call. The user can undo this. Returns the component's id.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The game object's id, from scene_tree or find_game_objects."
          },
          "type": {
            "type": "string",
            "description": "The component type name, e.g. 'ModelRenderer'. get_component_type documents what exists."
          },
          "properties": {
            "type": "object",
            "description": "Optional json object of property values, e.g. {\"LightColor\": \"1,0.8,0.6,1\", \"Radius\": 512}."
          }
        },
        "required": [
          "id",
          "type"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "string"
          },
          "Type": {
            "type": "string"
          },
          "GameObject": {
            "type": "string"
          }
        },
        "required": []
      }
    },
    {
      "name": "asset_dependencies",
      "title": "Asset Dependencies",
      "toolset": "asset",
      "description": "Walk an asset's relationships - the assets it references (uses), the assets that depend on it, or the assets it was generated from. Deep recurses the whole chain, e.g. a model's materials and their textures.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Asset path, as returned by asset_search."
          },
          "relation": {
            "type": "string",
            "enum": [
              "References",
              "Dependants",
              "Parents"
            ],
            "description": "Which direction to walk.",
            "default": "References"
          },
          "deep": {
            "type": "boolean",
            "description": "Recurse instead of returning only direct relationships.",
            "default": false
          },
          "type": {
            "type": "string",
            "description": "Filter results to one asset type - a file extension or friendly name. See asset_types."
          },
          "limit": {
            "type": "integer",
            "description": "How many results to return.",
            "minimum": 1,
            "maximum": 500,
            "default": 100
          }
        },
        "required": [
          "path"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Path": {
            "type": "string"
          },
          "Relation": {
            "type": "string"
          },
          "Total": {
            "type": "integer",
            "description": "How many related assets exist, beyond what's shown."
          },
          "Assets": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Path": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "asset_find_by_file",
      "title": "Asset Find By File",
      "toolset": "asset",
      "description": "Find the assets built from a loose disk file - which models use this .fbx, which textures use this .png. Matches the end of the path, so a filename is enough.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "file": {
            "type": "string",
            "description": "File path or filename, e.g. chair.fbx"
          },
          "limit": {
            "type": "integer",
            "description": "How many results to return.",
            "minimum": 1,
            "maximum": 500,
            "default": 50
          }
        },
        "required": [
          "file"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Total": {
            "type": "integer"
          },
          "Assets": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Path": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "asset_read",
      "title": "Asset Read",
      "toolset": "asset",
      "description": "Read a game resource asset's raw json - the actual data of a prefab, sound event, clothing definition or any other GameResource type. Doesn't work on binary assets like models and textures.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Asset path, as returned by asset_search."
          }
        },
        "required": [
          "path"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "asset_search",
      "title": "Asset Search",
      "toolset": "asset",
      "description": "Search the asset system by keywords and type. An empty query lists every asset, so use limit and offset to page through. Returns relative asset paths - pass one to asset_info, asset_compile, asset_read or asset_dependencies.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Space separated keywords. Every keyword must match the asset's path or one of its tags. Empty matches everything."
          },
          "type": {
            "type": "string",
            "description": "Filter to one asset type - a file extension (vmdl, vmat, prefab) or friendly name (Model, Material). See asset_types."
          },
          "projectOnly": {
            "type": "boolean",
            "description": "Only assets belonging to the currently open project, excluding engine content and cloud downloads.",
            "default": false
          },
          "unreferencedOnly": {
            "type": "boolean",
            "description": "Only assets nothing else references - useful for finding unused assets. Note map files and code can use an asset without the asset system knowing.",
            "default": false
          },
          "compileFailedOnly": {
            "type": "boolean",
            "description": "Only assets whose last compile failed.",
            "default": false
          },
          "uncompiledOnly": {
            "type": "boolean",
            "description": "Only assets with no compiled version at all.",
            "default": false
          },
          "limit": {
            "type": "integer",
            "description": "How many results to return.",
            "minimum": 1,
            "maximum": 500,
            "default": 50
          },
          "offset": {
            "type": "integer",
            "description": "How many results to skip, for paging.",
            "default": 0
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Total": {
            "type": "integer",
            "description": "How many assets matched in total, beyond this page."
          },
          "Showing": {
            "type": "integer"
          },
          "Offset": {
            "type": "integer"
          },
          "Assets": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Path": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "asset_thumbnail",
      "title": "Asset Thumbnail",
      "toolset": "asset",
      "description": "Render an asset's preview thumbnail and return it as an image - see what a model, material or texture actually looks like.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Asset path, as returned by asset_search."
          }
        },
        "required": [
          "path"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "asset_write",
      "title": "Asset Write",
      "toolset": "asset",
      "description": "Overwrite a game resource asset's json and recompile it. Read the current json with asset_read first, modify it, and pass the whole document back - this replaces the entire file. Doesn't work on binary assets like models and textures.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Asset path, as returned by asset_search."
          },
          "json": {
            "type": "string",
            "description": "The complete json document to write."
          }
        },
        "required": [
          "path",
          "json"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Success": {
            "type": "boolean"
          },
          "Path": {
            "type": "string"
          },
          "Hint": {
            "type": "string"
          }
        },
        "required": []
      }
    },
    {
      "name": "bridge_scatter_props",
      "title": "Native Scatter Props",
      "toolset": "bridge_helpers",
      "description": "Scatter model props with a repeatable seed, optional ground snapping, rotation, scaling and grouping. Requires stopped play mode. Uses the existing Bridge helper's scene and undo behaviour.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "model": {
            "type": "string",
            "description": "Project-relative model path, as returned by asset_search."
          },
          "center": {
            "type": "string",
            "description": "World-space centre as x,y,z, in Source units."
          },
          "radius": {
            "type": "number",
            "description": "Finite, nonnegative scatter radius in Source units.",
            "default": 256
          },
          "count": {
            "type": "integer",
            "description": "Number of props, from 1 to 300.",
            "default": 10
          },
          "seed": {
            "type": "integer",
            "description": "Nonnegative seed for repeatable placement.",
            "default": 1
          },
          "snapToGround": {
            "type": "boolean",
            "description": "Trace downward to place each prop on the ground.",
            "default": true
          },
          "randomYaw": {
            "type": "boolean",
            "description": "Randomise each prop's yaw.",
            "default": true
          },
          "scaleMin": {
            "type": "number",
            "description": "Positive minimum scale.",
            "default": 1
          },
          "scaleMax": {
            "type": "number",
            "description": "Maximum scale, at least scaleMin.",
            "default": 1
          },
          "group": {
            "type": "boolean",
            "description": "Parent the props under a new group object.",
            "default": true
          },
          "name": {
            "type": "string",
            "description": "Name prefix for the created objects.",
            "default": "Prop"
          }
        },
        "required": [
          "model",
          "center"
        ]
      }
    },
    {
      "name": "create_game_object",
      "title": "Create Game Object",
      "toolset": "scene",
      "description": "Create a game object in the active scene - empty or from a prefab, optionally with components. For putting a model in the scene, spawn_model is quicker. The user can undo this. Returns the new object's id for the other scene tools.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Name for the new object. Empty picks a sensible default."
          },
          "parent": {
            "type": "string",
            "description": "Parent game object id. Empty parents to the scene root."
          },
          "prefab": {
            "type": "string",
            "description": "Prefab asset path to instantiate, from asset_search."
          },
          "position": {
            "type": "string",
            "description": "World position as 'x,y,z'. Default origin."
          },
          "angles": {
            "type": "string",
            "description": "Rotation as 'pitch,yaw,roll'."
          },
          "scale": {
            "type": "string",
            "description": "Scale as 'x,y,z', or a single number for uniform."
          },
          "components": {
            "type": "string",
            "description": "Comma separated component type names to add, e.g. 'ModelRenderer,BoxCollider'."
          }
        },
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "Position": {
            "type": "string"
          },
          "Components": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                },
                "GameObject": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "find_packages",
      "title": "Find Packages",
      "toolset": "package",
      "description": "Search the backend for published packages - models, gamemodes, maps, addons. Plain words search text, and the query supports filters like 'type:model', 'type:gamemode', 'tag:fun' and 'sort:popular' mixed in with the search words.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Search query, e.g. 'barrel type:model sort:popular'."
          },
          "limit": {
            "type": "integer",
            "description": "How many results to return.",
            "minimum": 1,
            "maximum": 100,
            "default": 20
          },
          "offset": {
            "type": "integer",
            "description": "How many results to skip, for paging.",
            "default": 0
          }
        },
        "required": [
          "query"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "TotalCount": {
            "type": "integer",
            "description": "How many packages matched in total, beyond this page."
          },
          "Packages": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Ident": {
                  "type": "string",
                  "description": "The ident get_package and install_package take."
                },
                "Title": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                },
                "Org": {
                  "type": "string"
                },
                "Summary": {
                  "type": "string"
                },
                "Tags": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                },
                "VotesUp": {
                  "type": "integer"
                },
                "Updated": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "get_component_type",
      "title": "Get Component Type",
      "toolset": "component",
      "description": "Documentation for a component type by name - its class name, display title, description, group, and every inspector property with title, description, type and read-only state. Matches exact names first, then substrings; multiple substring matches come back as a candidate list.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "The component's type name, e.g. 'ModelRenderer'. Case insensitive, substrings work."
          }
        },
        "required": [
          "name"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "hammer_asset_usage",
      "title": "Asset Usage",
      "toolset": "hammer",
      "description": "Which assets the map uses and how heavily - mesh materials with how many faces, triangles and square units of surface they cover, models and other assets in entity keyvalues, and resources on game object components. Counts the map as placed: everything inside a prefab counts once per placement, nested prefabs included, so Nodes, Faces and Triangles track what gets drawn. With no asset, lists every asset sorted by 'sortBy'; give an asset to list where it's placed - inside a prefab, that's the prefab node placed in the map.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "asset": {
            "type": "string",
            "description": "An asset path to find users of. Empty summarises everything."
          },
          "sortBy": {
            "type": "string",
            "description": "Sort the summary by Nodes, Faces, Triangles or Area.",
            "default": "Nodes"
          },
          "includePrefabs": {
            "type": "boolean",
            "description": "Count what's inside prefabs placed in the map, not just the map's own nodes.",
            "default": true
          },
          "limit": {
            "type": "integer",
            "description": "How many entries to return.",
            "minimum": 1,
            "maximum": 1000,
            "default": 200
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "hammer_assign_asset",
      "title": "Assign Asset",
      "toolset": "hammer",
      "description": "Apply an asset to nodes the way dropping it onto them in Hammer does - a material paints every face of the meshes (or just the selected faces, in Faces mode), a model swaps a prop's model. Give node ids, or nothing to apply to the current selection. Selects the nodes it applied to. The user can undo this.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "asset": {
            "type": "string",
            "description": "The material or model asset path."
          },
          "ids": {
            "type": "array",
            "items": {
              "type": "integer"
            },
            "description": "Node ids to apply to. Empty applies to the current selection."
          }
        },
        "required": [
          "asset"
        ]
      }
    },
    {
      "name": "hammer_create_entity",
      "title": "Create Entity",
      "toolset": "hammer",
      "description": "Place an entity in the open map - a light, prop, spawn point, sound, anything hammer_entity_classes lists. Set any keyvalues in the same call. The user can undo this. Returns the new node.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "className": {
            "type": "string",
            "description": "The entity class, e.g. 'light_omni' or 'prop_static'. hammer_entity_classes lists them and documents their keyvalues."
          },
          "position": {
            "type": "string",
            "description": "World position as 'x,y,z'."
          },
          "angles": {
            "type": "string",
            "description": "Rotation as 'pitch,yaw,roll'."
          },
          "name": {
            "type": "string",
            "description": "The entity's name (targetname), for other entities to refer to it."
          },
          "keyValues": {
            "type": "object",
            "description": "Keyvalues as a json object, e.g. {\"model\": \"models/dev/box.vmdl\"} or {\"color\": \"255 200 150\"}. Strings are stored as given, numbers as written, booleans as 1/0 and arrays space separated - the way Hammer stores them."
          }
        },
        "required": [
          "className",
          "position"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "integer"
          },
          "Kind": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "ClassName": {
            "type": "string"
          },
          "Description": {
            "type": "string"
          },
          "Position": {
            "type": "string"
          },
          "Parent": {
            "type": "integer"
          },
          "GameObject": {
            "type": "string"
          },
          "Selected": {
            "type": "boolean"
          },
          "Visible": {
            "type": "boolean"
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_create_game_object",
      "title": "Create Game Object",
      "toolset": "hammer",
      "description": "Put a game object in the open map - empty, from a prefab, and/or with components and their properties set in the same call. This is how s&box gameplay goes in a map. The user can undo the creation. Returns the new node, whose GameObject field is the object's guid.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Name for the object. Empty uses the prefab's name, or 'GameObject'."
          },
          "position": {
            "type": "string",
            "description": "World position as 'x,y,z'."
          },
          "angles": {
            "type": "string",
            "description": "Rotation as 'pitch,yaw,roll'."
          },
          "prefab": {
            "type": "string",
            "description": "Prefab asset path to instantiate, from asset_search type:prefab."
          },
          "components": {
            "type": "object",
            "description": "Components to add, as a json object of type name to properties - e.g. {\"ModelRenderer\": {\"Model\": \"models/dev/box.vmdl\"}, \"BoxCollider\": {}}. get_component_type documents types and properties. A type the prefab already has gets its properties set instead."
          }
        },
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "integer"
          },
          "Kind": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "ClassName": {
            "type": "string"
          },
          "Description": {
            "type": "string"
          },
          "Position": {
            "type": "string"
          },
          "Parent": {
            "type": "integer"
          },
          "GameObject": {
            "type": "string"
          },
          "Selected": {
            "type": "boolean"
          },
          "Visible": {
            "type": "boolean"
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_select",
      "title": "Select",
      "toolset": "hammer",
      "description": "Change Hammer's selection - select nodes by id and/or everything using an asset, optionally switching selection mode first. Selecting is how you show the user what you mean, and some tools (hammer_run_command, hammer_assign_asset) act on the selection. Returns the new selection.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "ids": {
            "type": "array",
            "items": {
              "type": "integer"
            },
            "description": "Node ids to select. Empty selects nothing by id."
          },
          "usingAsset": {
            "type": "string",
            "description": "Also select every node using this asset - a model or material path."
          },
          "add": {
            "type": "boolean",
            "description": "Add to the current selection instead of replacing it.",
            "default": false
          },
          "mode": {
            "type": "string",
            "enum": [
              "Groups",
              "Objects",
              "Meshes",
              "Verticies",
              "Edges",
              "Faces",
              "Nav",
              "Tiles"
            ],
            "description": "Switch selection mode first - Groups, Objects or Meshes. Empty keeps the current mode."
          }
        },
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Mode": {
            "type": "string"
          },
          "Pivot": {
            "type": "string"
          },
          "Count": {
            "type": "integer"
          },
          "Nodes": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "integer"
                },
                "Kind": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "ClassName": {
                  "type": "string"
                },
                "Description": {
                  "type": "string"
                },
                "Position": {
                  "type": "string"
                },
                "Parent": {
                  "type": "integer"
                },
                "GameObject": {
                  "type": "string"
                },
                "Selected": {
                  "type": "boolean"
                },
                "Visible": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "install_package",
      "title": "Install Package",
      "toolset": "package",
      "description": "Download and install a cloud package into the project so its assets can be used - after this the returned asset path works anywhere an asset path does, e.g. spawn_model for a model package. Already-installed packages return immediately.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "ident": {
            "type": "string",
            "description": "The package ident, like 'facepunch.wooden_crate' or from find_packages."
          }
        },
        "required": [
          "ident"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Ident": {
            "type": "string"
          },
          "AssetPath": {
            "type": "string",
            "description": "The primary asset's path - works anywhere an asset path does."
          },
          "AssetType": {
            "type": "string"
          }
        },
        "required": []
      }
    },
    {
      "name": "spawn_model",
      "title": "Spawn Model",
      "toolset": "scene",
